INSERT INTO sources(source_key,title,title_fa,organization_or_author,language_code,source_type,url,locator,locator_fa,published_or_updated_at,modernity_status,currency_evidence,license_name,license_url,attribution_text,reuse_status,retrieved_at,notes) VALUES
('src-wikibooks-de-lesson-007-food-order','Deutschkurs für Anfänger/Lektion 007','سفارش چندقلمی و ترجیح ساده','Wikibooks contributors','de','course','https://en.wikibooks.org/wiki/Deutschkurs_f%C3%BCr_Anf%C3%A4nger/Lektion_007','Items 286 and 288: simple preferences and multi-item snack-bar ordering with an additional-item prompt.','بخش‌های ۲۸۶ و ۲۸۸؛ ترجیح ساده و سفارش خوراکی و نوشیدنی با پرسش دربارهٔ قلم دیگری که مشتری می‌خواهد.','2025-01-04','contemporary_verified','صفحهٔ زندهٔ ویکی‌بوکس در ۱۷ سپتامبر ۲۰۲۶ بررسی شد و آخرین ویرایش ثبت‌شدهٔ آن ۴ ژانویهٔ ۲۰۲۵ است. جمله‌های انتخاب‌شده دربارهٔ سفارش چندقلمی، افزودن یک قلم دیگر و بیان ترجیح ساده در بازبینی فعلی طبیعی و مناسب A1 هستند.','CC BY-SA 4.0','https://creativecommons.org/licenses/by-sa/4.0/','Wikibooks contributors — Deutschkurs für Anfänger/Lektion 007','reuse_with_attribution','2026-09-17','استفاده به بخش‌های ۲۸۶ و ۲۸۸ محدود است. بخش ۲۸۸ یک سفارش دو مرحله‌ای منسجم و چند نمونهٔ جایگزین دارد و بخش ۲۸۶ ترجیح ساده با رد یک خوراکی یا نوشیدنی را فراهم می‌کند. جمله‌های آلمانی بدون بازنویسی وارد محتوا می‌شوند.')
INSERT INTO units(unit_key,language_level_id,sequence_index,title_fa,grouping_rationale,status,metadata,notes) VALUES
('de-a1-unit-expanded-food-order',@level,6,'سفارش گسترده‌تر غذا و نوشیدنی','سطح پیشین سفارش تک‌قلمی را معرفی کرده بود. این واحد همان موقعیت را به سفارش چندمرحله‌ای گسترش می‌دهد: یک خوراکی، پرسش فروشنده برای قلم دیگر، افزودن نوشیدنی و تشخیص ترجیح ساده. همهٔ این اجزا در دو بخش نزدیک از یک منبع واحد قرار دارند.','review',JSON_OBJECT('sourceRefs',JSON_ARRAY('src-wikibooks-de-lesson-007-food-order'),'learningTargets',JSON_ARRAY('سفارش بیش از یک قلم','فهم پرسش چیز دیگری','تشخیص ترجیح ساده','فهم تکه و فنجان')),'بازبینی پوشش انجام شد. گفت‌وگوی اصلی سفارش دو قلم را پوشش می‌دهد، تمرین‌های همان منبع چند ترکیب دیگر و ترجیح ساده را اضافه می‌کنند و نسبت به سفارش تک‌قلمی سطح پیشین گسترش واقعی ایجاد شده است. برای هدف فعلی این واحد شکاف ضروری مستقلی برای درس دوم پیدا نشد.')
