(@src,'srcitem-de-a1-food-3','288','بخش ۲۸۸','Noch was bitte?',UNHEX(SHA2('Noch was bitte?',256)),'پرسش دربارهٔ قلم دیگر.'),
(@src,'srcitem-de-a1-food-4','288','بخش ۲۸۸','Ich möchte auch noch eine Tasse Kaffee.',UNHEX(SHA2('Ich möchte auch noch eine Tasse Kaffee.',256)),'افزودن نوشیدنی.'),
(@src,'srcitem-de-a1-food-pref-coffee','286','بخش ۲۸۶','Ich möchte Kaffee, aber keine Milch.',UNHEX(SHA2('Ich möchte Kaffee, aber keine Milch.',256)),'ترجیح قهوه بدون شیر.'),
