(@src,'srcitem-de-a1-food-three-cake','288','بخش ۲۸۸','Ich möchte drei Stück Kuchen.',UNHEX(SHA2('Ich möchte drei Stück Kuchen.',256)),'نمونهٔ چند تکه کیک.'),
