INSERT INTO lessons(lesson_key,language_level_id,unit_id,sequence_index,position_in_unit,title_fa,source_title,source_title_fa,status,activity_selection_rationale,sequence_rationale,template_signature,audio_status,notes) VALUES
('de-a1-lesson-expanded-food-order',@level,@unit,10,1,'چیز دیگری هم؟','Was möchten Sie? / Noch was bitte?','چه میل دارید؟ / چیز دیگری هم؟','draft','گفت‌وگو سفارش دو مرحله‌ای را می‌سازد؛ سپس ترجیح ساده با سه جملهٔ منبع‌دار سنجیده می‌شود، چهار ترکیب سفارش به معنی فارسی وصل می‌شوند و در پایان پاسخ افزودن قهوه بازسازی می‌شود.','درس از تعامل کامل به تمایز ترجیح، شناخت ترکیب‌های سفارش و بازیابی فعال نوبت مشتری حرکت می‌کند و نسبت به درس خرید قبلی الگوی فعالیت متفاوتی دارد.','conversation_speaking>multiple_choice>matching>word_order','blocked_until_level_final','یک گفت‌وگوی منبع‌دار چهار نوبتی هستهٔ واحد را می‌سازد و تمرین‌های نزدیک همان منبع ترجیح و ترکیب‌های دیگر را اضافه می‌کنند.')
