INSERT INTO dialogues(dialogue_key,language_level_id,scenario,opening_initiator,scene_quality_rationale) VALUES
('dlg-de-a1-expanded-food-order',@level,'یوناس در نقش کارمند کافه سفارش لنا را می‌گیرد. لنا ابتدا یک تکه کیک می‌خواهد و بعد از پرسش یوناس یک فنجان قهوه هم به سفارش اضافه می‌کند.','app','چهار نوبت نخست نمونهٔ ۲۸۸ عیناً حفظ شده‌اند و یک سفارش طبیعی دو مرحله‌ای می‌سازند. نقش کارمند کافهٔ یوناس با خطاب رسمی منبع و سناریوی خدماتی سازگار است.')
