('turn-de-a1-food-order-3',@dialogue,3,@jonas,'app_assigned','unspecified','Noch was bitte?','چیز دیگری هم؟',FALSE,'blocked_until_level_final'),
('turn-de-a1-food-order-4',@dialogue,4,@lena,'app_assigned','unspecified','Ich möchte auch noch eine Tasse Kaffee.','یک فنجان قهوه هم می‌خواهم.',TRUE,'blocked_until_level_final')
INSERT INTO activities(activity_key,lesson_id,position_index,activity_type,instruction_fa,selection_reason,dialogue_id,payload,transformations,audio_text_target,audio_status) VALUES
('act-de-a1-expanded-food-conversation',@lesson,1,'conversation_speaking','یک تکه کیک سفارش بده و بعد قهوه را هم به سفارشت اضافه کن.','چهار نوبت پیوستهٔ منبع، سفارش چندقلمی و پرسش رایج فروشنده برای قلم دیگر را بدون جمله‌سازی آزاد پوشش می‌دهند.',@dialogue,JSON_OBJECT('interaction','read_aloud_exchange','openingInitiator','app'),JSON_ARRAY('verbatim_dialogue','persian_translation_added','character_metadata_added'),NULL,'not_required'),
('act-de-a1-food-preference-choice',@lesson,2,'multiple_choice','کدام جمله می‌گوید قهوه می‌خواهم، اما شیر نمی‌خواهم؟','سه جملهٔ کامل و منبع‌دار یک الگوی سادهٔ ترجیح و رد را با خوراکی‌های متفاوت مقایسه می‌کنند.',NULL,JSON_OBJECT('options',JSON_ARRAY(JSON_OBJECT('textTarget','Ich möchte Kaffee, aber keine Milch.','translationFa','قهوه می‌خواهم، اما شیر نمی‌خواهم.','correct',TRUE),JSON_OBJECT('textTarget','Ich möchte Kuchen, aber keine Brötchen.','translationFa','کیک می‌خواهم، اما نان گرد نمی‌خواهم.','correct',FALSE),JSON_OBJECT('textTarget','Ich möchte Reis, aber keine Suppe.','translationFa','برنج می‌خواهم، اما سوپ نمی‌خواهم.','correct',FALSE))),JSON_ARRAY('options_selected_from_source_material','persian_translation_added'),NULL,'not_required'),
('act-de-a1-food-combinations-matching',@lesson,3,'matching','هر ترکیب سفارش را به معنی درستش وصل کن.','چهار ترکیب از نمونه‌های بخش ۲۸۸ تکه، فنجان و افزودنی‌های ساده را در بافت سفارش تثبیت می‌کنند.',NULL,JSON_OBJECT('pairs',JSON_ARRAY(JSON_OBJECT('left','ein Stück Kuchen','leftFa','یک تکه کیک','right','یک تکه کیک','rightFa','یک تکه کیک'),JSON_OBJECT('left','eine Tasse Kaffee','leftFa','یک فنجان قهوه','right','یک فنجان قهوه','rightFa','یک فنجان قهوه'),JSON_OBJECT('left','drei Stück Kuchen','leftFa','سه تکه کیک','right','سه تکه کیک','rightFa','سه تکه کیک'),JSON_OBJECT('left','eine Tasse Kaffee mit Milch und Zucker','leftFa','یک فنجان قهوه با شیر و شکر','right','قهوه با شیر و شکر','rightFa','قهوه با شیر و شکر'))),JSON_ARRAY('source_items_grouped_for_matching','persian_translation_added'),NULL,'not_required'),
('act-de-a1-food-add-coffee-order',@lesson,4,'word_order','جملهٔ اضافه کردن قهوه به سفارش را دوباره بساز.','آخرین نوبت مشتری پس از فهم و تشخیص به بازیابی فعال منتقل می‌شود.',NULL,JSON_OBJECT('sourceText','Ich möchte auch noch eine Tasse Kaffee.','sourceTextFa','یک فنجان قهوه هم می‌خواهم.','tokens',JSON_ARRAY('Ich','möchte','auch','noch','eine','Tasse','Kaffee.'),'answer',JSON_ARRAY('Ich','möchte','auch','noch','eine','Tasse','Kaffee.')),JSON_ARRAY('sentence_tokenized_for_word_order','persian_translation_added'),NULL,'not_required')
